def count_0_sum_paths(grid):
  R, C = len(grid), len(grid[0])
  memo = {}

  def num_paths(r, c):
    if r >= R or c >= C or grid[r][c] == 1:
      return 0
    if (r, c) in memo:
      return memo[(r, c)]
    if r == R - 1 and c == C - 1:
      return 1
    memo[(r, c)] = num_paths(r + 1, c) + \
        num_paths(r, c + 1) + num_paths(r + 1, c + 1)
    return memo[(r, c)]

  return num_paths(0, 0)

